-- Explicitly requested initial batch: 30 fictional stories, one per new writer.
-- Idempotent inserts; actual publication timestamps. Does not alter votes or real stories.
BEGIN;
SET LOCAL lock_timeout = '5s';
INSERT INTO public.sample_stories (id,source_key,author_id,title,content,starter_sentence,word_count,time_mode,mode,is_hardcore,created_at,provenance)
SELECT id,source_key,author_id,title,content,starter_sentence,word_count,time_mode,mode,is_hardcore,now(),
 'Original AI-written fiction; timestamp is actual editorial publication, not a real writing session.'
FROM jsonb_to_recordset($initial$[{"title": "The blue bowl", "content": "\"You put it in the fridge.\" \"Why would I put an empty bowl in the fridge?\" \"I don't know why you do most things.\" My sister was still holding the spoon, pointing it into cupboards like she could detect porcelain with it. I said maybe she'd taken it to work. She said she hadn't worked there since February. Right. I knew that. I was trying to remember whether I had said anything else about work since she got here. The kettle clicked off and neither of us moved. \"There's the green one,\" I said. \"I know there's the green one.\" She opened the fridge. The blue bowl was inside, under a plate, full of the cherries I'd saved for her. \"Oh,\" she said. I told her she could wash them herself, I wasn't doing everything.", "starter_sentence": "Someone had moved the only thing I needed.", "word_count": 135, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "4e30ddcc-9a23-5b98-87f9-a378e19676bb", "source_key": "sample-story-4e30ddcc-9a23-5b98-87f9-a378e19676bb", "author_id": "0d1e3567-fc38-5476-9d1b-d1506407e589"}, {"title": "Eight millimetres", "content": "The new bolt was eight millimetres too long. I had measured it with the nut still on, which is something I would laugh at anyone else for doing. Cut it down. Couldn't get the nut back over the cut end. Filed it. Too much. By lunchtime the bicycle was in more pieces than when I started. My son asked if we were still going to the canal. I said bring your shoes. We walked the bicycle there. He rode it down the slope with his feet out and I carried the pedals in my pocket.", "starter_sentence": "The replacement part almost fit.", "word_count": 95, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "71003911-e4e7-5aa2-b110-9cb9dfede361", "source_key": "sample-story-71003911-e4e7-5aa2-b110-9cb9dfede361", "author_id": "4e278577-2b14-5dbf-9d79-acacd25506ba"}, {"title": "voice note", "content": "it wasn't even the worst recording on my phone which is what i keep trying to explain. The worst one is me practising how to say happy birthday without sounding like I had practised. This one was just forty seconds of me complaining about the birthday dinner. To the birthday person. no wait to the GROUP with the birthday person in it, so worse actually. I held my thumb on the message and the phone offered to save it. why would i want to save it. preserve it for my children. By the time I found delete she'd sent a voice note back. I put the phone under a cushion so I couldnt see the length of it. My brother came in and sat on the cushion and now the thing was playing into his leg and I could hear her laughing but not what she was saying", "starter_sentence": "I sent the wrong recording.", "word_count": 148, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "0e8fd503-5c37-5e04-b132-1d86e81a2ebd", "source_key": "sample-story-0e8fd503-5c37-5e04-b132-1d86e81a2ebd", "author_id": "d7866188-9db8-52b5-bc17-abc99c5a47ba"}, {"title": "Application for shade", "content": "1. Bring proof that the tree is yours. A photograph of yourself standing beside it will not count. Anyone can stand beside a tree.\n2. Bring the tree, if possible.\n3. If not possible, bring a letter from the tree explaining why.\nI asked the woman behind the glass whether a leaf would do. She considered this seriously enough that I became hopeful. A leaf with a signature, she said. I went outside. The tree was still there, shading four people who had not applied for anything. I put the form against the trunk to write on it and a pigeon deposited something beside the signature box. Back inside she said the stamp was in the wrong place.", "starter_sentence": "The office needed one more document.", "word_count": 118, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "92a2f050-386c-5c10-9358-d154b7271020", "source_key": "sample-story-92a2f050-386c-5c10-9358-d154b7271020", "author_id": "a6c99e39-f8d7-5e97-8741-8515787a7f27"}, {"title": "next door", "content": "three notes then the chair scraping. every evening. i know where the fourth note goes now, i hum it while washing up. tonight somebody else is playing, all the way through, very well. i leave the tap running so i can't hear how well.", "starter_sentence": "The music stopped halfway through.", "word_count": 44, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "d705be98-eab8-58ef-adad-4ea565974e46", "source_key": "sample-story-d705be98-eab8-58ef-adad-4ea565974e46", "author_id": "682e8ef3-1e0e-5dab-b653-3b53a1f35608"}, {"title": "Two coats and a goal", "content": "Look it was in. Your coat was the post and the ball went inside your coat. Then you picked your coat up because a car was coming and apparently the goal moved with it. I have never heard of that rule. We were four two up anyway, or four three if we're counting the one off the dog which I said we shouldn't. Everyone was shouting and the little kid from the second floor walked right between us with a bottle of water. He poured two lines on the ground. There. Posts. We all looked at them. Actually quite sensible. We started again and within five minutes one line had dried before the other so now we had a completely diffrent argument. I was goalkeeper this time. I'm telling you the sun was on their side.", "starter_sentence": "We disagreed about where the line was.", "word_count": 136, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "b3541f10-6597-5063-83ff-4dc8657a12a7", "source_key": "sample-story-b3541f10-6597-5063-83ff-4dc8657a12a7", "author_id": "81e0836c-79de-575e-99f3-0d29fbb949aa"}, {"title": "The last hook", "content": "The brass hook was screwed into the back of the bedroom door. She had hung a school bag there, then a towel, then nothing for several years. Her mother watched her test it with two fingers. It wouldn't turn. In the car her husband was making room for the last box. She could hear the boot opening and closing. Her mother went to the kitchen and returned with a screwdriver, the small one with a cracked yellow handle. She put it on the windowsill and left without asking what it was for.", "starter_sentence": "She had already packed everything useful.", "word_count": 92, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "1af20da5-9f40-5dd0-a43e-e15143f3b3ed", "source_key": "sample-story-1af20da5-9f40-5dd0-a43e-e15143f3b3ed", "author_id": "c960b079-39f4-539f-9939-09bb823740ee"}, {"title": "Apricots", "content": "Potatoes first. Then onions because they're cheaper at the other end, though you spend the saving walking there. Bought apricots I hadn't planned on. The man gave me one to try and stood watching while I ate it. Hard to say no with your mouth full. By the bus stop one bag handle had stretched into a string. Swapped hands every twenty steps. At home my daughter counted the apricots into a bowl. Seventeen. She wanted to know who got the extra one. I said me, carrying fee. She cut it into three pieces because her mother was coming home later. Mine was mostly stone. I ate it standing up while she explained the division again. Apparently I had misunderstood.", "starter_sentence": "The bag weighed more than it should have.", "word_count": 120, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "43f2cb27-9e70-59ed-9e2a-0480b381d294", "source_key": "sample-story-43f2cb27-9e70-59ed-9e2a-0480b381d294", "author_id": "8d394b17-0d66-52ab-a18e-b41d5c61b265"}, {"title": "Undo", "content": "a button that takes you back ten seconds but only the last ten seconds you enjoyed. so if you're having a terrible day it might send you back to breakfast. wait that isn't ten seconds backwards thats selecting a memory isn't it. ok it takes your BODY there. you're thirty and suddenly sitting in a tiny chair at your seventh birthday and everyone screams except your grandmother who just moves the cake knife out of your reach. She says you've come back then. I think she knows how it works. I think she's been doing this for years which explains why she always knew when the doorbell was about to go. But where does seven year old you go. there are two of you and only one party hat and", "starter_sentence": "The button only worked once.", "word_count": 130, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "92051503-a911-51cf-a81c-af15a891cbc2", "source_key": "sample-story-92051503-a911-51cf-a81c-af15a891cbc2", "author_id": "78699f80-eb9e-515c-9609-6540e7adf2e0"}, {"title": "Landing", "content": "Three flights up. The sound stayed one flight ahead although I was taking the stairs two at a time. At the next landing I stopped. It stopped too. Pipes, I thought. There were pipes along the ceiling. I went up backwards watching the empty flight below because somehow that seemed the sensible thing to do. My heel hit something soft. A shopping bag, tied at the handles. Warm bread inside, I could smell it through the plastic. Whoever had left it was standing behind the fire door. I could see the edge of a shoe under it. \"You dropped this.\" The shoe moved back. The light went off. I knew the switch was beside the door but I couldn't remember which side.", "starter_sentence": "There were footsteps above me.", "word_count": 122, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "f31e254d-7a3f-5857-9e8a-e60d067842da", "source_key": "sample-story-f31e254d-7a3f-5857-9e8a-e60d067842da", "author_id": "09dc47a1-b470-5bdd-b915-41d527a6b0f3"}, {"title": "the good pen", "content": "borrowed a pen for the exam and it was one of those with four colours so obviously i spent the first minute deciding which blue was more serious. there was only one blue. other button was purple. wrote my NAME in purple before discovering this and now i looked like someone with a whole personality instead of someone who had revised on the bus. first question: discuss. Discuss WHAT i wanted to ask, emotionally. i clicked the black button and the entire spring came out. guy beside me caught it without looking up. honestly most impressive thing anyone did in that room", "starter_sentence": "I had brought everything except the important thing.", "word_count": 102, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c", "source_key": "sample-story-280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c", "author_id": "7b440e7a-5591-56ba-83cc-fc217b347ada"}, {"title": "The vine", "content": "The vine has reached the upstairs window. You said it would if I stopped cutting it. I stopped because the ladder broke, so you can be right for the wrong reason. There are grapes but they're small and the birds get there first. I moved your chair into the shade. The leg still needs fixing. Everyone who visits chooses the other chair even when I tell them this one's safe. I don't know why I keep telling them. Your brother came on Tuesday with a bag of screws, none of them the right size. We drank tea standing up. He asked if I wanted him to take the chair away and I said I was sitting in it. I wasn't. He didn't say anything about that.", "starter_sentence": "There was something I had forgotten to tell you.", "word_count": 126, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "42ee0c93-45b0-5483-ad98-6262a37c87d3", "source_key": "sample-story-42ee0c93-45b0-5483-ad98-6262a37c87d3", "author_id": "4cb8da3a-5049-5c9e-ae8a-734f593e0b87"}, {"title": "A little more water", "content": "Auntie said a glass of water but her glass was that thick old one with the flowers and mine was much bigger, so already we had a problem. Add flour till it's right she said over the phone. What does right look like. You know. I didn't know, that was the purpose of calling. My daughter pushed one finger into it and the whole bowl followed her hand up. Too wet, auntie said when I described this. More flour. Then more water because now it was a brick. We were making enough for a wedding by this point and there were three of us eating. I put the phone on the counter and heard auntie laughing with somebody in her kitchen. I wanted to be annoyed but I wanted to be in her kitchen more. My daughter was making a very small animal out of dough. She said it was me.", "starter_sentence": "Nobody had written down the recipe.", "word_count": 151, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "c03efad1-cd94-58d6-b40f-420566e91060", "source_key": "sample-story-c03efad1-cd94-58d6-b40f-420566e91060", "author_id": "b0addcb6-0723-5073-9710-41fb3486c732"}, {"title": "Tank six", "content": "Tank six reports ninety litres more than yesterday. No intake recorded. No neighbouring tank shows a loss. I checked the sensor with a bucket and a marked stick, as instructed. The stick came back dry. The bucket came back full. Requesting a second bucket. Also requesting that whoever writes the instructions stop adding exclamation marks after the word simple. Update: the sample is salt water. We do not carry salt water. I have covered the inspection window because something on the other side is following the torch.", "starter_sentence": "The reading had changed overnight.", "word_count": 87, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "12e9f4e0-3181-5c98-820b-41291f00d814", "source_key": "sample-story-12e9f4e0-3181-5c98-820b-41291f00d814", "author_id": "3b608dd1-8159-5317-a916-27e58f6b5b9d"}, {"title": "Not her wedding", "content": "She said she wasn't coming which everyone took personally, but I thought she meant the photographer. She was pointing at his car. Or the car behind his car. Anyway by the time it reached our table it was the groom who wasn't coming and somebody had started putting the salads back in the fridge. I told them don't do that, you don't know anything yet. Neither did I but I was holding a plate so I looked involved. The bride came out in slippers and asked why her uncle was crying. He said happy tears. He'd been saying the marriage was a mistake thirty seconds before. Then the photographer arrived carrying a tyre and she said SEE. I still don't understand what that proved but we all went back for the salads.", "starter_sentence": "I only heard half the conversation.", "word_count": 132, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "4a6db8ef-c566-590d-9c29-219be4b91e1c", "source_key": "sample-story-4a6db8ef-c566-590d-9c29-219be4b91e1c", "author_id": "a5b516db-9000-59d2-b4e5-34ae6288fd48"}, {"title": "Below the ridge", "content": "My left sock had worked its way under my heel. I kept stopping to pull it up and my sister kept pretending to look at the view. When we reached the snow she went ahead. I watched her boots make two neat holes, two more. Mine slid sideways. Wind got under my coat and pushed it against my back. I wanted to say we should turn round but she had already sat down to untie her boots. She handed me one of her socks. Hers were much too big. We went another fifty metres before either of us spoke.", "starter_sentence": "We were nearly at the top.", "word_count": 99, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "4ac02c70-f34c-5ee9-a3a0-fe5eea638875", "source_key": "sample-story-4ac02c70-f34c-5ee9-a3a0-fe5eea638875", "author_id": "bce314a6-b6c0-517e-8519-b2b1289ea16e"}, {"title": "The passenger", "content": "I said forty kilometres. He said good. Put his sack in the back and got in. After ten minutes the sack crowed. I looked at him. He looked out the window. At the next village he paid for two passengers. I gave him change for one.", "starter_sentence": "He asked if I was going far.", "word_count": 46, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "421c3e6c-2642-5939-b117-5713eec9d2a3", "source_key": "sample-story-421c3e6c-2642-5939-b117-5713eec9d2a3", "author_id": "a4e73876-53a0-54d4-8be6-31ff102ddabe"}, {"title": "Spin cycle", "content": "the small grey cloud came out with the towels, i thought it was steam until it followed me to the balcony. shook the towel and it rained on my feet. well fine. put a bowl under it. it floated away from the bowl because apparently even weather can be difficult before breakfast. My neighbour leaned over and said hers had done that when she used too much powder. She had a whole thunderstorm in the spare room once. I asked how she got rid of it and she said she didnt, her son liked the noise for sleeping. The cloud settled over my basil. By evening the basil looked better than it had in months so I left the window open a crack, just enough for it to come in if it wanted", "starter_sentence": "There was something alive in the laundry.", "word_count": 133, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "834ba1a7-bbf8-5e89-ab41-583268f83300", "source_key": "sample-story-834ba1a7-bbf8-5e89-ab41-583268f83300", "author_id": "61179e3d-48ee-5367-9c5f-272ac8085853"}, {"title": "What came back", "content": "Returned: two mugs, one drill, the red blanket. Not returned: extension lead, three books, the lid for the big saucepan. In the drill case I found a photograph from the day we put the shelves up. Both of us covered in plaster dust. The shelves had fallen down before dinner because we'd used the wrong plugs and we'd eaten on the floor underneath the holes, laughing so much I thought the neighbour would knock. I added the photograph to the list. Crossed it out. Put the lidless saucepan on top of everything and carried it upstairs.", "starter_sentence": "We counted the boxes twice.", "word_count": 96, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "5622ce7d-4fea-5083-b98d-6f9da059bf57", "source_key": "sample-story-5622ce7d-4fea-5083-b98d-6f9da059bf57", "author_id": "c01828e7-2a62-56df-b08d-df4139dbce03"}, {"title": "The oranges", "content": "Take the oranges out of the plastic bag before you go in. The bag makes too much noise. Don't ask if she's tired. She'll say no and keep talking until she is. Pull the chair close enough that she doesn't have to raise her voice. Not that close, you're on the tube. When she asks about the garden tell her the truth about the roses and lie about the weeds. Peel an orange. She'll say she doesn't want it. Leave one piece on the napkin beside her hand. Talk about the bus, the rain, anything that happened outside. When she falls asleep stay until the piece of orange is gone or until", "starter_sentence": "They told me the visit had to be short.", "word_count": 112, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "532c513e-a1f6-55cc-8214-f54eabaf69bd", "source_key": "sample-story-532c513e-a1f6-55cc-8214-f54eabaf69bd", "author_id": "1c86406f-0ed6-51e0-a81e-08001b901bbb"}, {"title": "The spoon rule", "content": "I'm not against rules. I have rules. For example do not use my mug to grow an avocado. Apparently that was unreasonable because the avocado had roots already and moving it would cause stress. The avocado lives in my mug. I drink from a measuring jug. But now there's a rule about teaspoons, specifically that each person gets two, and I want to know who counted them because there were nine yesterday and there are four of us. Who has the ninth spoon. Is it communal. Is it for the avocado. Nobody will answer this directly. They say this is why we need a house meeting. I say a house meeting should require chairs and somebody has put all the chairs on the balcony to dry after washing them for reasons that were also not discussed", "starter_sentence": "There was a new note on the fridge.", "word_count": 136, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "7d056d4b-f699-5c60-8fd6-47400de9c2b0", "source_key": "sample-story-7d056d4b-f699-5c60-8fd6-47400de9c2b0", "author_id": "72801aaa-6c97-50f4-9640-48b16ec4b073"}, {"title": "Platform photograph", "content": "The boy's sleeve was caught under his mother's suitcase handle. He could have pulled it out. He stayed leaning sideways instead, one shoulder lower than the other. Behind them a man folded a newspaper into smaller and smaller squares without reading it. The train hadn't arrived. I lifted the camera. The boy looked straight at me and tucked his free hand into the trapped sleeve. In the photograph it looks as though his mother is holding him. Her own hands are both in her pockets.", "starter_sentence": "Only one person noticed the camera.", "word_count": 85, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "ea6b3334-245d-5bd4-805e-1da1cd1f4212", "source_key": "sample-story-ea6b3334-245d-5bd4-805e-1da1cd1f4212", "author_id": "fc425770-e917-5a6d-acc8-ca8daa11fc1b"}, {"title": "Number 46", "content": "Forty four. So I have time to work out what to say. Hello, I booked online. No obviously I booked online they have the booking. Just hello. Forty five goes in carrying a folder and I havent brought a folder. Was there a folder requirement. I look at the email again but the screen rotates and now it's huge and I can't find the bit with my name. A woman comes out and smiles at me in a way that might mean it's my turn or might just mean she is a person who smiles. I half stand. She walks past. Sit. The chair makes that noise. Everyone has heard the chair. Now I need to explain the chair before I can explain why I'm here. Forty six. I stand up properly and say sorry to the man who called my number. Haven't done anything yet. Already sorry.", "starter_sentence": "My number was almost next.", "word_count": 148, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "faa87a38-75da-516e-b01a-4a9a5f77e111", "source_key": "sample-story-faa87a38-75da-516e-b01a-4a9a5f77e111", "author_id": "eca9f8e7-f8b7-558f-8207-481485400330"}, {"title": "The wrong village", "content": "The important thing about that holiday was the cheese, although my wife says it was getting lost with no fuel, but we had some fuel, the light was only orange. We stopped in a village where a man was repairing a chair outside his shop and I asked him the way with the map upside down, which he politely turned round before telling me we were on the wrong side of the mountain. He gave us cheese while he explained. Very good cheese. I asked where to buy it and he said his brother made it and went inside to call him. My wife was in the car looking at the petrol light. The brother came on a motorbike with a whole wheel under his arm. We had to put it on her lap. She says this is the part of the story I should start with.", "starter_sentence": "We took the turning with the broken sign.", "word_count": 147, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "f3374cfe-c941-5c98-86b5-e22367a66c35", "source_key": "sample-story-f3374cfe-c941-5c98-86b5-e22367a66c35", "author_id": "5b0eeceb-76d5-583d-bed0-39afe01504fb"}, {"title": "The warm side", "content": "I turned the pillow over. The other side was warm too. I stood up. On the mattress, the hollow where I'd been lying began to deepen. Slowly, as though someone much heavier was settling into the space. I reached for the lamp and felt", "starter_sentence": "The room looked exactly as I had left it.", "word_count": 44, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "78e52dc9-e3ee-574c-885e-f5cfef1f1757", "source_key": "sample-story-78e52dc9-e3ee-574c-885e-f5cfef1f1757", "author_id": "69b1ca7b-7919-5593-9644-3ab1b8eb14e1"}, {"title": "Curtain rail", "content": "The first hole was fine. Second one hit something that made a noise I didn't recognise. Turned the drill off. Noise continued. Turned the radio off. Still going. It was my neighbour on the other side, drilling back. We met in the corridor holding identical drills like a very disappointing duel. He said he'd been putting up shelves. I said curtain rail. We compared the holes through his wall. Mine was higher. I felt pleased about that for no reason at all. Then his wife came out with the little bag of wall plugs we'd both forgotten to use.", "starter_sentence": "I said it would take ten minutes.", "word_count": 99, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "9d3523a2-e9c1-5de4-af22-c8c2886e259f", "source_key": "sample-story-9d3523a2-e9c1-5de4-af22-c8c2886e259f", "author_id": "2fee657f-01df-5589-9703-afda3541f074"}, {"title": "The end seat", "content": "She put her shopping on the end seat and kept looking at the door. The café filled. A man asked if the chair was taken and she said yes, quickly, then moved one bag to her lap as though that made it more convincing. I brought her another glass of water. She asked what time we closed. Four. Plenty of time, she said. At ten to four a woman in a cycling helmet came in and stood beside the chair. Neither smiled. The bags went on the floor. I was wiping the counter when I heard one of them say, I didn't know if you'd still be here. I left the cloth where it was and went to find something to do in the kitchen.", "starter_sentence": "She saved a place for someone who wasn't there.", "word_count": 125, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "e499097b-cd67-5140-a5c8-1068367e31bc", "source_key": "sample-story-e499097b-cd67-5140-a5c8-1068367e31bc", "author_id": "f353f630-d0c7-55ec-b980-d6a969560c1c"}, {"title": "One free minute", "content": "Buy one hour, get one minute free. I asked what kind of hour. Any kind, said the shopkeeper, except an hour you have already used. I bought an hour of sleep. He gave me an hour of waiting for sleep. I complained. You were in bed, he said. I asked for my free minute. He handed me a small paper bag. Inside was the minute before I had entered his shop. I used it to walk past. He came running after me asking for the bag back.", "starter_sentence": "The shopkeeper offered me a bargain.", "word_count": 87, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "4bc23cd7-05be-5ff9-a591-8fa0cd313623", "source_key": "sample-story-4bc23cd7-05be-5ff9-a591-8fa0cd313623", "author_id": "d7117dcb-cf9f-5fc7-9a99-7f5ffc586ffb"}, {"title": "NOT our cat", "content": "found the cat!! carried him upstairs like a baby despite his opinions on this and rang mum to say stop looking. she said the cat is here. I said no he isnt he's in my ARMS. she said then who's eating tuna in my kitchen. looked down. this cat had a white foot. ours has no white feet. how many times have i looked at my own cat?? apparently not enough. tried taking him back down but he'd got comfortable and now i was the unreasonable one. downstairs there was a woman shaking a bag of treats and crying and i went over holding him out like an apology with legs. she hugged the cat then me then said he never lets strangers pick him up. great. exceptional talent discovered at last. accidental cat theft", "starter_sentence": "I was so relieved that I forgot to check.", "word_count": 135, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "7cc36beb-809a-5641-b612-ba819eee47fe", "source_key": "sample-story-7cc36beb-809a-5641-b612-ba819eee47fe", "author_id": "72714dea-7aef-5a4a-8fd7-ad9f7a20e4aa"}, {"title": "Last carriage", "content": "A wet umbrella stood against the empty seat. At each station it leaned toward the open door, then straightened when the doors closed. I moved my bag so there would be room beside it.", "starter_sentence": "The rain stopped at the door.", "word_count": 34, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "24cb4af3-4e23-5633-9a98-92205d216561", "source_key": "sample-story-24cb4af3-4e23-5633-9a98-92205d216561", "author_id": "757950cd-75de-5f59-ba49-d64a93bf4bcd"}]$initial$::jsonb)
AS x(id uuid,source_key text,author_id uuid,title text,content text,starter_sentence text,word_count integer,time_mode integer,mode text,is_hardcore boolean)
ON CONFLICT (id) DO NOTHING;
UPDATE public.sample_profiles p SET
 total_stories=(SELECT count(*) FROM public.sample_stories s WHERE s.author_id=p.id AND NOT s.is_hidden),
 total_words=(SELECT coalesce(sum(word_count),0) FROM public.sample_stories s WHERE s.author_id=p.id AND NOT s.is_hidden)
WHERE id IN (SELECT (value->>'author_id')::uuid FROM jsonb_array_elements($initial$[{"title": "The blue bowl", "content": "\"You put it in the fridge.\" \"Why would I put an empty bowl in the fridge?\" \"I don't know why you do most things.\" My sister was still holding the spoon, pointing it into cupboards like she could detect porcelain with it. I said maybe she'd taken it to work. She said she hadn't worked there since February. Right. I knew that. I was trying to remember whether I had said anything else about work since she got here. The kettle clicked off and neither of us moved. \"There's the green one,\" I said. \"I know there's the green one.\" She opened the fridge. The blue bowl was inside, under a plate, full of the cherries I'd saved for her. \"Oh,\" she said. I told her she could wash them herself, I wasn't doing everything.", "starter_sentence": "Someone had moved the only thing I needed.", "word_count": 135, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "4e30ddcc-9a23-5b98-87f9-a378e19676bb", "source_key": "sample-story-4e30ddcc-9a23-5b98-87f9-a378e19676bb", "author_id": "0d1e3567-fc38-5476-9d1b-d1506407e589"}, {"title": "Eight millimetres", "content": "The new bolt was eight millimetres too long. I had measured it with the nut still on, which is something I would laugh at anyone else for doing. Cut it down. Couldn't get the nut back over the cut end. Filed it. Too much. By lunchtime the bicycle was in more pieces than when I started. My son asked if we were still going to the canal. I said bring your shoes. We walked the bicycle there. He rode it down the slope with his feet out and I carried the pedals in my pocket.", "starter_sentence": "The replacement part almost fit.", "word_count": 95, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "71003911-e4e7-5aa2-b110-9cb9dfede361", "source_key": "sample-story-71003911-e4e7-5aa2-b110-9cb9dfede361", "author_id": "4e278577-2b14-5dbf-9d79-acacd25506ba"}, {"title": "voice note", "content": "it wasn't even the worst recording on my phone which is what i keep trying to explain. The worst one is me practising how to say happy birthday without sounding like I had practised. This one was just forty seconds of me complaining about the birthday dinner. To the birthday person. no wait to the GROUP with the birthday person in it, so worse actually. I held my thumb on the message and the phone offered to save it. why would i want to save it. preserve it for my children. By the time I found delete she'd sent a voice note back. I put the phone under a cushion so I couldnt see the length of it. My brother came in and sat on the cushion and now the thing was playing into his leg and I could hear her laughing but not what she was saying", "starter_sentence": "I sent the wrong recording.", "word_count": 148, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "0e8fd503-5c37-5e04-b132-1d86e81a2ebd", "source_key": "sample-story-0e8fd503-5c37-5e04-b132-1d86e81a2ebd", "author_id": "d7866188-9db8-52b5-bc17-abc99c5a47ba"}, {"title": "Application for shade", "content": "1. Bring proof that the tree is yours. A photograph of yourself standing beside it will not count. Anyone can stand beside a tree.\n2. Bring the tree, if possible.\n3. If not possible, bring a letter from the tree explaining why.\nI asked the woman behind the glass whether a leaf would do. She considered this seriously enough that I became hopeful. A leaf with a signature, she said. I went outside. The tree was still there, shading four people who had not applied for anything. I put the form against the trunk to write on it and a pigeon deposited something beside the signature box. Back inside she said the stamp was in the wrong place.", "starter_sentence": "The office needed one more document.", "word_count": 118, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "92a2f050-386c-5c10-9358-d154b7271020", "source_key": "sample-story-92a2f050-386c-5c10-9358-d154b7271020", "author_id": "a6c99e39-f8d7-5e97-8741-8515787a7f27"}, {"title": "next door", "content": "three notes then the chair scraping. every evening. i know where the fourth note goes now, i hum it while washing up. tonight somebody else is playing, all the way through, very well. i leave the tap running so i can't hear how well.", "starter_sentence": "The music stopped halfway through.", "word_count": 44, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "d705be98-eab8-58ef-adad-4ea565974e46", "source_key": "sample-story-d705be98-eab8-58ef-adad-4ea565974e46", "author_id": "682e8ef3-1e0e-5dab-b653-3b53a1f35608"}, {"title": "Two coats and a goal", "content": "Look it was in. Your coat was the post and the ball went inside your coat. Then you picked your coat up because a car was coming and apparently the goal moved with it. I have never heard of that rule. We were four two up anyway, or four three if we're counting the one off the dog which I said we shouldn't. Everyone was shouting and the little kid from the second floor walked right between us with a bottle of water. He poured two lines on the ground. There. Posts. We all looked at them. Actually quite sensible. We started again and within five minutes one line had dried before the other so now we had a completely diffrent argument. I was goalkeeper this time. I'm telling you the sun was on their side.", "starter_sentence": "We disagreed about where the line was.", "word_count": 136, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "b3541f10-6597-5063-83ff-4dc8657a12a7", "source_key": "sample-story-b3541f10-6597-5063-83ff-4dc8657a12a7", "author_id": "81e0836c-79de-575e-99f3-0d29fbb949aa"}, {"title": "The last hook", "content": "The brass hook was screwed into the back of the bedroom door. She had hung a school bag there, then a towel, then nothing for several years. Her mother watched her test it with two fingers. It wouldn't turn. In the car her husband was making room for the last box. She could hear the boot opening and closing. Her mother went to the kitchen and returned with a screwdriver, the small one with a cracked yellow handle. She put it on the windowsill and left without asking what it was for.", "starter_sentence": "She had already packed everything useful.", "word_count": 92, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "1af20da5-9f40-5dd0-a43e-e15143f3b3ed", "source_key": "sample-story-1af20da5-9f40-5dd0-a43e-e15143f3b3ed", "author_id": "c960b079-39f4-539f-9939-09bb823740ee"}, {"title": "Apricots", "content": "Potatoes first. Then onions because they're cheaper at the other end, though you spend the saving walking there. Bought apricots I hadn't planned on. The man gave me one to try and stood watching while I ate it. Hard to say no with your mouth full. By the bus stop one bag handle had stretched into a string. Swapped hands every twenty steps. At home my daughter counted the apricots into a bowl. Seventeen. She wanted to know who got the extra one. I said me, carrying fee. She cut it into three pieces because her mother was coming home later. Mine was mostly stone. I ate it standing up while she explained the division again. Apparently I had misunderstood.", "starter_sentence": "The bag weighed more than it should have.", "word_count": 120, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "43f2cb27-9e70-59ed-9e2a-0480b381d294", "source_key": "sample-story-43f2cb27-9e70-59ed-9e2a-0480b381d294", "author_id": "8d394b17-0d66-52ab-a18e-b41d5c61b265"}, {"title": "Undo", "content": "a button that takes you back ten seconds but only the last ten seconds you enjoyed. so if you're having a terrible day it might send you back to breakfast. wait that isn't ten seconds backwards thats selecting a memory isn't it. ok it takes your BODY there. you're thirty and suddenly sitting in a tiny chair at your seventh birthday and everyone screams except your grandmother who just moves the cake knife out of your reach. She says you've come back then. I think she knows how it works. I think she's been doing this for years which explains why she always knew when the doorbell was about to go. But where does seven year old you go. there are two of you and only one party hat and", "starter_sentence": "The button only worked once.", "word_count": 130, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "92051503-a911-51cf-a81c-af15a891cbc2", "source_key": "sample-story-92051503-a911-51cf-a81c-af15a891cbc2", "author_id": "78699f80-eb9e-515c-9609-6540e7adf2e0"}, {"title": "Landing", "content": "Three flights up. The sound stayed one flight ahead although I was taking the stairs two at a time. At the next landing I stopped. It stopped too. Pipes, I thought. There were pipes along the ceiling. I went up backwards watching the empty flight below because somehow that seemed the sensible thing to do. My heel hit something soft. A shopping bag, tied at the handles. Warm bread inside, I could smell it through the plastic. Whoever had left it was standing behind the fire door. I could see the edge of a shoe under it. \"You dropped this.\" The shoe moved back. The light went off. I knew the switch was beside the door but I couldn't remember which side.", "starter_sentence": "There were footsteps above me.", "word_count": 122, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "f31e254d-7a3f-5857-9e8a-e60d067842da", "source_key": "sample-story-f31e254d-7a3f-5857-9e8a-e60d067842da", "author_id": "09dc47a1-b470-5bdd-b915-41d527a6b0f3"}, {"title": "the good pen", "content": "borrowed a pen for the exam and it was one of those with four colours so obviously i spent the first minute deciding which blue was more serious. there was only one blue. other button was purple. wrote my NAME in purple before discovering this and now i looked like someone with a whole personality instead of someone who had revised on the bus. first question: discuss. Discuss WHAT i wanted to ask, emotionally. i clicked the black button and the entire spring came out. guy beside me caught it without looking up. honestly most impressive thing anyone did in that room", "starter_sentence": "I had brought everything except the important thing.", "word_count": 102, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c", "source_key": "sample-story-280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c", "author_id": "7b440e7a-5591-56ba-83cc-fc217b347ada"}, {"title": "The vine", "content": "The vine has reached the upstairs window. You said it would if I stopped cutting it. I stopped because the ladder broke, so you can be right for the wrong reason. There are grapes but they're small and the birds get there first. I moved your chair into the shade. The leg still needs fixing. Everyone who visits chooses the other chair even when I tell them this one's safe. I don't know why I keep telling them. Your brother came on Tuesday with a bag of screws, none of them the right size. We drank tea standing up. He asked if I wanted him to take the chair away and I said I was sitting in it. I wasn't. He didn't say anything about that.", "starter_sentence": "There was something I had forgotten to tell you.", "word_count": 126, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "42ee0c93-45b0-5483-ad98-6262a37c87d3", "source_key": "sample-story-42ee0c93-45b0-5483-ad98-6262a37c87d3", "author_id": "4cb8da3a-5049-5c9e-ae8a-734f593e0b87"}, {"title": "A little more water", "content": "Auntie said a glass of water but her glass was that thick old one with the flowers and mine was much bigger, so already we had a problem. Add flour till it's right she said over the phone. What does right look like. You know. I didn't know, that was the purpose of calling. My daughter pushed one finger into it and the whole bowl followed her hand up. Too wet, auntie said when I described this. More flour. Then more water because now it was a brick. We were making enough for a wedding by this point and there were three of us eating. I put the phone on the counter and heard auntie laughing with somebody in her kitchen. I wanted to be annoyed but I wanted to be in her kitchen more. My daughter was making a very small animal out of dough. She said it was me.", "starter_sentence": "Nobody had written down the recipe.", "word_count": 151, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "c03efad1-cd94-58d6-b40f-420566e91060", "source_key": "sample-story-c03efad1-cd94-58d6-b40f-420566e91060", "author_id": "b0addcb6-0723-5073-9710-41fb3486c732"}, {"title": "Tank six", "content": "Tank six reports ninety litres more than yesterday. No intake recorded. No neighbouring tank shows a loss. I checked the sensor with a bucket and a marked stick, as instructed. The stick came back dry. The bucket came back full. Requesting a second bucket. Also requesting that whoever writes the instructions stop adding exclamation marks after the word simple. Update: the sample is salt water. We do not carry salt water. I have covered the inspection window because something on the other side is following the torch.", "starter_sentence": "The reading had changed overnight.", "word_count": 87, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "12e9f4e0-3181-5c98-820b-41291f00d814", "source_key": "sample-story-12e9f4e0-3181-5c98-820b-41291f00d814", "author_id": "3b608dd1-8159-5317-a916-27e58f6b5b9d"}, {"title": "Not her wedding", "content": "She said she wasn't coming which everyone took personally, but I thought she meant the photographer. She was pointing at his car. Or the car behind his car. Anyway by the time it reached our table it was the groom who wasn't coming and somebody had started putting the salads back in the fridge. I told them don't do that, you don't know anything yet. Neither did I but I was holding a plate so I looked involved. The bride came out in slippers and asked why her uncle was crying. He said happy tears. He'd been saying the marriage was a mistake thirty seconds before. Then the photographer arrived carrying a tyre and she said SEE. I still don't understand what that proved but we all went back for the salads.", "starter_sentence": "I only heard half the conversation.", "word_count": 132, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "4a6db8ef-c566-590d-9c29-219be4b91e1c", "source_key": "sample-story-4a6db8ef-c566-590d-9c29-219be4b91e1c", "author_id": "a5b516db-9000-59d2-b4e5-34ae6288fd48"}, {"title": "Below the ridge", "content": "My left sock had worked its way under my heel. I kept stopping to pull it up and my sister kept pretending to look at the view. When we reached the snow she went ahead. I watched her boots make two neat holes, two more. Mine slid sideways. Wind got under my coat and pushed it against my back. I wanted to say we should turn round but she had already sat down to untie her boots. She handed me one of her socks. Hers were much too big. We went another fifty metres before either of us spoke.", "starter_sentence": "We were nearly at the top.", "word_count": 99, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "4ac02c70-f34c-5ee9-a3a0-fe5eea638875", "source_key": "sample-story-4ac02c70-f34c-5ee9-a3a0-fe5eea638875", "author_id": "bce314a6-b6c0-517e-8519-b2b1289ea16e"}, {"title": "The passenger", "content": "I said forty kilometres. He said good. Put his sack in the back and got in. After ten minutes the sack crowed. I looked at him. He looked out the window. At the next village he paid for two passengers. I gave him change for one.", "starter_sentence": "He asked if I was going far.", "word_count": 46, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "421c3e6c-2642-5939-b117-5713eec9d2a3", "source_key": "sample-story-421c3e6c-2642-5939-b117-5713eec9d2a3", "author_id": "a4e73876-53a0-54d4-8be6-31ff102ddabe"}, {"title": "Spin cycle", "content": "the small grey cloud came out with the towels, i thought it was steam until it followed me to the balcony. shook the towel and it rained on my feet. well fine. put a bowl under it. it floated away from the bowl because apparently even weather can be difficult before breakfast. My neighbour leaned over and said hers had done that when she used too much powder. She had a whole thunderstorm in the spare room once. I asked how she got rid of it and she said she didnt, her son liked the noise for sleeping. The cloud settled over my basil. By evening the basil looked better than it had in months so I left the window open a crack, just enough for it to come in if it wanted", "starter_sentence": "There was something alive in the laundry.", "word_count": 133, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "834ba1a7-bbf8-5e89-ab41-583268f83300", "source_key": "sample-story-834ba1a7-bbf8-5e89-ab41-583268f83300", "author_id": "61179e3d-48ee-5367-9c5f-272ac8085853"}, {"title": "What came back", "content": "Returned: two mugs, one drill, the red blanket. Not returned: extension lead, three books, the lid for the big saucepan. In the drill case I found a photograph from the day we put the shelves up. Both of us covered in plaster dust. The shelves had fallen down before dinner because we'd used the wrong plugs and we'd eaten on the floor underneath the holes, laughing so much I thought the neighbour would knock. I added the photograph to the list. Crossed it out. Put the lidless saucepan on top of everything and carried it upstairs.", "starter_sentence": "We counted the boxes twice.", "word_count": 96, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "5622ce7d-4fea-5083-b98d-6f9da059bf57", "source_key": "sample-story-5622ce7d-4fea-5083-b98d-6f9da059bf57", "author_id": "c01828e7-2a62-56df-b08d-df4139dbce03"}, {"title": "The oranges", "content": "Take the oranges out of the plastic bag before you go in. The bag makes too much noise. Don't ask if she's tired. She'll say no and keep talking until she is. Pull the chair close enough that she doesn't have to raise her voice. Not that close, you're on the tube. When she asks about the garden tell her the truth about the roses and lie about the weeds. Peel an orange. She'll say she doesn't want it. Leave one piece on the napkin beside her hand. Talk about the bus, the rain, anything that happened outside. When she falls asleep stay until the piece of orange is gone or until", "starter_sentence": "They told me the visit had to be short.", "word_count": 112, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "532c513e-a1f6-55cc-8214-f54eabaf69bd", "source_key": "sample-story-532c513e-a1f6-55cc-8214-f54eabaf69bd", "author_id": "1c86406f-0ed6-51e0-a81e-08001b901bbb"}, {"title": "The spoon rule", "content": "I'm not against rules. I have rules. For example do not use my mug to grow an avocado. Apparently that was unreasonable because the avocado had roots already and moving it would cause stress. The avocado lives in my mug. I drink from a measuring jug. But now there's a rule about teaspoons, specifically that each person gets two, and I want to know who counted them because there were nine yesterday and there are four of us. Who has the ninth spoon. Is it communal. Is it for the avocado. Nobody will answer this directly. They say this is why we need a house meeting. I say a house meeting should require chairs and somebody has put all the chairs on the balcony to dry after washing them for reasons that were also not discussed", "starter_sentence": "There was a new note on the fridge.", "word_count": 136, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "7d056d4b-f699-5c60-8fd6-47400de9c2b0", "source_key": "sample-story-7d056d4b-f699-5c60-8fd6-47400de9c2b0", "author_id": "72801aaa-6c97-50f4-9640-48b16ec4b073"}, {"title": "Platform photograph", "content": "The boy's sleeve was caught under his mother's suitcase handle. He could have pulled it out. He stayed leaning sideways instead, one shoulder lower than the other. Behind them a man folded a newspaper into smaller and smaller squares without reading it. The train hadn't arrived. I lifted the camera. The boy looked straight at me and tucked his free hand into the trapped sleeve. In the photograph it looks as though his mother is holding him. Her own hands are both in her pockets.", "starter_sentence": "Only one person noticed the camera.", "word_count": 85, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "ea6b3334-245d-5bd4-805e-1da1cd1f4212", "source_key": "sample-story-ea6b3334-245d-5bd4-805e-1da1cd1f4212", "author_id": "fc425770-e917-5a6d-acc8-ca8daa11fc1b"}, {"title": "Number 46", "content": "Forty four. So I have time to work out what to say. Hello, I booked online. No obviously I booked online they have the booking. Just hello. Forty five goes in carrying a folder and I havent brought a folder. Was there a folder requirement. I look at the email again but the screen rotates and now it's huge and I can't find the bit with my name. A woman comes out and smiles at me in a way that might mean it's my turn or might just mean she is a person who smiles. I half stand. She walks past. Sit. The chair makes that noise. Everyone has heard the chair. Now I need to explain the chair before I can explain why I'm here. Forty six. I stand up properly and say sorry to the man who called my number. Haven't done anything yet. Already sorry.", "starter_sentence": "My number was almost next.", "word_count": 148, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "faa87a38-75da-516e-b01a-4a9a5f77e111", "source_key": "sample-story-faa87a38-75da-516e-b01a-4a9a5f77e111", "author_id": "eca9f8e7-f8b7-558f-8207-481485400330"}, {"title": "The wrong village", "content": "The important thing about that holiday was the cheese, although my wife says it was getting lost with no fuel, but we had some fuel, the light was only orange. We stopped in a village where a man was repairing a chair outside his shop and I asked him the way with the map upside down, which he politely turned round before telling me we were on the wrong side of the mountain. He gave us cheese while he explained. Very good cheese. I asked where to buy it and he said his brother made it and went inside to call him. My wife was in the car looking at the petrol light. The brother came on a motorbike with a whole wheel under his arm. We had to put it on her lap. She says this is the part of the story I should start with.", "starter_sentence": "We took the turning with the broken sign.", "word_count": 147, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "f3374cfe-c941-5c98-86b5-e22367a66c35", "source_key": "sample-story-f3374cfe-c941-5c98-86b5-e22367a66c35", "author_id": "5b0eeceb-76d5-583d-bed0-39afe01504fb"}, {"title": "The warm side", "content": "I turned the pillow over. The other side was warm too. I stood up. On the mattress, the hollow where I'd been lying began to deepen. Slowly, as though someone much heavier was settling into the space. I reached for the lamp and felt", "starter_sentence": "The room looked exactly as I had left it.", "word_count": 44, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "78e52dc9-e3ee-574c-885e-f5cfef1f1757", "source_key": "sample-story-78e52dc9-e3ee-574c-885e-f5cfef1f1757", "author_id": "69b1ca7b-7919-5593-9644-3ab1b8eb14e1"}, {"title": "Curtain rail", "content": "The first hole was fine. Second one hit something that made a noise I didn't recognise. Turned the drill off. Noise continued. Turned the radio off. Still going. It was my neighbour on the other side, drilling back. We met in the corridor holding identical drills like a very disappointing duel. He said he'd been putting up shelves. I said curtain rail. We compared the holes through his wall. Mine was higher. I felt pleased about that for no reason at all. Then his wife came out with the little bag of wall plugs we'd both forgotten to use.", "starter_sentence": "I said it would take ten minutes.", "word_count": 99, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "9d3523a2-e9c1-5de4-af22-c8c2886e259f", "source_key": "sample-story-9d3523a2-e9c1-5de4-af22-c8c2886e259f", "author_id": "2fee657f-01df-5589-9703-afda3541f074"}, {"title": "The end seat", "content": "She put her shopping on the end seat and kept looking at the door. The café filled. A man asked if the chair was taken and she said yes, quickly, then moved one bag to her lap as though that made it more convincing. I brought her another glass of water. She asked what time we closed. Four. Plenty of time, she said. At ten to four a woman in a cycling helmet came in and stood beside the chair. Neither smiled. The bags went on the floor. I was wiping the counter when I heard one of them say, I didn't know if you'd still be here. I left the cloth where it was and went to find something to do in the kitchen.", "starter_sentence": "She saved a place for someone who wasn't there.", "word_count": 125, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "e499097b-cd67-5140-a5c8-1068367e31bc", "source_key": "sample-story-e499097b-cd67-5140-a5c8-1068367e31bc", "author_id": "f353f630-d0c7-55ec-b980-d6a969560c1c"}, {"title": "One free minute", "content": "Buy one hour, get one minute free. I asked what kind of hour. Any kind, said the shopkeeper, except an hour you have already used. I bought an hour of sleep. He gave me an hour of waiting for sleep. I complained. You were in bed, he said. I asked for my free minute. He handed me a small paper bag. Inside was the minute before I had entered his shop. I used it to walk past. He came running after me asking for the bag back.", "starter_sentence": "The shopkeeper offered me a bargain.", "word_count": 87, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "4bc23cd7-05be-5ff9-a591-8fa0cd313623", "source_key": "sample-story-4bc23cd7-05be-5ff9-a591-8fa0cd313623", "author_id": "d7117dcb-cf9f-5fc7-9a99-7f5ffc586ffb"}, {"title": "NOT our cat", "content": "found the cat!! carried him upstairs like a baby despite his opinions on this and rang mum to say stop looking. she said the cat is here. I said no he isnt he's in my ARMS. she said then who's eating tuna in my kitchen. looked down. this cat had a white foot. ours has no white feet. how many times have i looked at my own cat?? apparently not enough. tried taking him back down but he'd got comfortable and now i was the unreasonable one. downstairs there was a woman shaking a bag of treats and crying and i went over holding him out like an apology with legs. she hugged the cat then me then said he never lets strangers pick him up. great. exceptional talent discovered at last. accidental cat theft", "starter_sentence": "I was so relieved that I forgot to check.", "word_count": 135, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "7cc36beb-809a-5641-b612-ba819eee47fe", "source_key": "sample-story-7cc36beb-809a-5641-b612-ba819eee47fe", "author_id": "72714dea-7aef-5a4a-8fd7-ad9f7a20e4aa"}, {"title": "Last carriage", "content": "A wet umbrella stood against the empty seat. At each station it leaned toward the open door, then straightened when the doors closed. I moved my bag so there would be room beside it.", "starter_sentence": "The rain stopped at the door.", "word_count": 34, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "24cb4af3-4e23-5633-9a98-92205d216561", "source_key": "sample-story-24cb4af3-4e23-5633-9a98-92205d216561", "author_id": "757950cd-75de-5f59-ba49-d64a93bf4bcd"}]$initial$::jsonb));
COMMIT;
SELECT id,author_username,title,word_count,created_at FROM public.community_stories
WHERE id IN (SELECT (value->>'id')::uuid FROM jsonb_array_elements($initial$[{"title": "The blue bowl", "content": "\"You put it in the fridge.\" \"Why would I put an empty bowl in the fridge?\" \"I don't know why you do most things.\" My sister was still holding the spoon, pointing it into cupboards like she could detect porcelain with it. I said maybe she'd taken it to work. She said she hadn't worked there since February. Right. I knew that. I was trying to remember whether I had said anything else about work since she got here. The kettle clicked off and neither of us moved. \"There's the green one,\" I said. \"I know there's the green one.\" She opened the fridge. The blue bowl was inside, under a plate, full of the cherries I'd saved for her. \"Oh,\" she said. I told her she could wash them herself, I wasn't doing everything.", "starter_sentence": "Someone had moved the only thing I needed.", "word_count": 135, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "4e30ddcc-9a23-5b98-87f9-a378e19676bb", "source_key": "sample-story-4e30ddcc-9a23-5b98-87f9-a378e19676bb", "author_id": "0d1e3567-fc38-5476-9d1b-d1506407e589"}, {"title": "Eight millimetres", "content": "The new bolt was eight millimetres too long. I had measured it with the nut still on, which is something I would laugh at anyone else for doing. Cut it down. Couldn't get the nut back over the cut end. Filed it. Too much. By lunchtime the bicycle was in more pieces than when I started. My son asked if we were still going to the canal. I said bring your shoes. We walked the bicycle there. He rode it down the slope with his feet out and I carried the pedals in my pocket.", "starter_sentence": "The replacement part almost fit.", "word_count": 95, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "71003911-e4e7-5aa2-b110-9cb9dfede361", "source_key": "sample-story-71003911-e4e7-5aa2-b110-9cb9dfede361", "author_id": "4e278577-2b14-5dbf-9d79-acacd25506ba"}, {"title": "voice note", "content": "it wasn't even the worst recording on my phone which is what i keep trying to explain. The worst one is me practising how to say happy birthday without sounding like I had practised. This one was just forty seconds of me complaining about the birthday dinner. To the birthday person. no wait to the GROUP with the birthday person in it, so worse actually. I held my thumb on the message and the phone offered to save it. why would i want to save it. preserve it for my children. By the time I found delete she'd sent a voice note back. I put the phone under a cushion so I couldnt see the length of it. My brother came in and sat on the cushion and now the thing was playing into his leg and I could hear her laughing but not what she was saying", "starter_sentence": "I sent the wrong recording.", "word_count": 148, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "0e8fd503-5c37-5e04-b132-1d86e81a2ebd", "source_key": "sample-story-0e8fd503-5c37-5e04-b132-1d86e81a2ebd", "author_id": "d7866188-9db8-52b5-bc17-abc99c5a47ba"}, {"title": "Application for shade", "content": "1. Bring proof that the tree is yours. A photograph of yourself standing beside it will not count. Anyone can stand beside a tree.\n2. Bring the tree, if possible.\n3. If not possible, bring a letter from the tree explaining why.\nI asked the woman behind the glass whether a leaf would do. She considered this seriously enough that I became hopeful. A leaf with a signature, she said. I went outside. The tree was still there, shading four people who had not applied for anything. I put the form against the trunk to write on it and a pigeon deposited something beside the signature box. Back inside she said the stamp was in the wrong place.", "starter_sentence": "The office needed one more document.", "word_count": 118, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "92a2f050-386c-5c10-9358-d154b7271020", "source_key": "sample-story-92a2f050-386c-5c10-9358-d154b7271020", "author_id": "a6c99e39-f8d7-5e97-8741-8515787a7f27"}, {"title": "next door", "content": "three notes then the chair scraping. every evening. i know where the fourth note goes now, i hum it while washing up. tonight somebody else is playing, all the way through, very well. i leave the tap running so i can't hear how well.", "starter_sentence": "The music stopped halfway through.", "word_count": 44, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "d705be98-eab8-58ef-adad-4ea565974e46", "source_key": "sample-story-d705be98-eab8-58ef-adad-4ea565974e46", "author_id": "682e8ef3-1e0e-5dab-b653-3b53a1f35608"}, {"title": "Two coats and a goal", "content": "Look it was in. Your coat was the post and the ball went inside your coat. Then you picked your coat up because a car was coming and apparently the goal moved with it. I have never heard of that rule. We were four two up anyway, or four three if we're counting the one off the dog which I said we shouldn't. Everyone was shouting and the little kid from the second floor walked right between us with a bottle of water. He poured two lines on the ground. There. Posts. We all looked at them. Actually quite sensible. We started again and within five minutes one line had dried before the other so now we had a completely diffrent argument. I was goalkeeper this time. I'm telling you the sun was on their side.", "starter_sentence": "We disagreed about where the line was.", "word_count": 136, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "b3541f10-6597-5063-83ff-4dc8657a12a7", "source_key": "sample-story-b3541f10-6597-5063-83ff-4dc8657a12a7", "author_id": "81e0836c-79de-575e-99f3-0d29fbb949aa"}, {"title": "The last hook", "content": "The brass hook was screwed into the back of the bedroom door. She had hung a school bag there, then a towel, then nothing for several years. Her mother watched her test it with two fingers. It wouldn't turn. In the car her husband was making room for the last box. She could hear the boot opening and closing. Her mother went to the kitchen and returned with a screwdriver, the small one with a cracked yellow handle. She put it on the windowsill and left without asking what it was for.", "starter_sentence": "She had already packed everything useful.", "word_count": 92, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "1af20da5-9f40-5dd0-a43e-e15143f3b3ed", "source_key": "sample-story-1af20da5-9f40-5dd0-a43e-e15143f3b3ed", "author_id": "c960b079-39f4-539f-9939-09bb823740ee"}, {"title": "Apricots", "content": "Potatoes first. Then onions because they're cheaper at the other end, though you spend the saving walking there. Bought apricots I hadn't planned on. The man gave me one to try and stood watching while I ate it. Hard to say no with your mouth full. By the bus stop one bag handle had stretched into a string. Swapped hands every twenty steps. At home my daughter counted the apricots into a bowl. Seventeen. She wanted to know who got the extra one. I said me, carrying fee. She cut it into three pieces because her mother was coming home later. Mine was mostly stone. I ate it standing up while she explained the division again. Apparently I had misunderstood.", "starter_sentence": "The bag weighed more than it should have.", "word_count": 120, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "43f2cb27-9e70-59ed-9e2a-0480b381d294", "source_key": "sample-story-43f2cb27-9e70-59ed-9e2a-0480b381d294", "author_id": "8d394b17-0d66-52ab-a18e-b41d5c61b265"}, {"title": "Undo", "content": "a button that takes you back ten seconds but only the last ten seconds you enjoyed. so if you're having a terrible day it might send you back to breakfast. wait that isn't ten seconds backwards thats selecting a memory isn't it. ok it takes your BODY there. you're thirty and suddenly sitting in a tiny chair at your seventh birthday and everyone screams except your grandmother who just moves the cake knife out of your reach. She says you've come back then. I think she knows how it works. I think she's been doing this for years which explains why she always knew when the doorbell was about to go. But where does seven year old you go. there are two of you and only one party hat and", "starter_sentence": "The button only worked once.", "word_count": 130, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "92051503-a911-51cf-a81c-af15a891cbc2", "source_key": "sample-story-92051503-a911-51cf-a81c-af15a891cbc2", "author_id": "78699f80-eb9e-515c-9609-6540e7adf2e0"}, {"title": "Landing", "content": "Three flights up. The sound stayed one flight ahead although I was taking the stairs two at a time. At the next landing I stopped. It stopped too. Pipes, I thought. There were pipes along the ceiling. I went up backwards watching the empty flight below because somehow that seemed the sensible thing to do. My heel hit something soft. A shopping bag, tied at the handles. Warm bread inside, I could smell it through the plastic. Whoever had left it was standing behind the fire door. I could see the edge of a shoe under it. \"You dropped this.\" The shoe moved back. The light went off. I knew the switch was beside the door but I couldn't remember which side.", "starter_sentence": "There were footsteps above me.", "word_count": 122, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "f31e254d-7a3f-5857-9e8a-e60d067842da", "source_key": "sample-story-f31e254d-7a3f-5857-9e8a-e60d067842da", "author_id": "09dc47a1-b470-5bdd-b915-41d527a6b0f3"}, {"title": "the good pen", "content": "borrowed a pen for the exam and it was one of those with four colours so obviously i spent the first minute deciding which blue was more serious. there was only one blue. other button was purple. wrote my NAME in purple before discovering this and now i looked like someone with a whole personality instead of someone who had revised on the bus. first question: discuss. Discuss WHAT i wanted to ask, emotionally. i clicked the black button and the entire spring came out. guy beside me caught it without looking up. honestly most impressive thing anyone did in that room", "starter_sentence": "I had brought everything except the important thing.", "word_count": 102, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c", "source_key": "sample-story-280e46e4-eca3-5c16-8aa9-d4dc15cb2f2c", "author_id": "7b440e7a-5591-56ba-83cc-fc217b347ada"}, {"title": "The vine", "content": "The vine has reached the upstairs window. You said it would if I stopped cutting it. I stopped because the ladder broke, so you can be right for the wrong reason. There are grapes but they're small and the birds get there first. I moved your chair into the shade. The leg still needs fixing. Everyone who visits chooses the other chair even when I tell them this one's safe. I don't know why I keep telling them. Your brother came on Tuesday with a bag of screws, none of them the right size. We drank tea standing up. He asked if I wanted him to take the chair away and I said I was sitting in it. I wasn't. He didn't say anything about that.", "starter_sentence": "There was something I had forgotten to tell you.", "word_count": 126, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "42ee0c93-45b0-5483-ad98-6262a37c87d3", "source_key": "sample-story-42ee0c93-45b0-5483-ad98-6262a37c87d3", "author_id": "4cb8da3a-5049-5c9e-ae8a-734f593e0b87"}, {"title": "A little more water", "content": "Auntie said a glass of water but her glass was that thick old one with the flowers and mine was much bigger, so already we had a problem. Add flour till it's right she said over the phone. What does right look like. You know. I didn't know, that was the purpose of calling. My daughter pushed one finger into it and the whole bowl followed her hand up. Too wet, auntie said when I described this. More flour. Then more water because now it was a brick. We were making enough for a wedding by this point and there were three of us eating. I put the phone on the counter and heard auntie laughing with somebody in her kitchen. I wanted to be annoyed but I wanted to be in her kitchen more. My daughter was making a very small animal out of dough. She said it was me.", "starter_sentence": "Nobody had written down the recipe.", "word_count": 151, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "c03efad1-cd94-58d6-b40f-420566e91060", "source_key": "sample-story-c03efad1-cd94-58d6-b40f-420566e91060", "author_id": "b0addcb6-0723-5073-9710-41fb3486c732"}, {"title": "Tank six", "content": "Tank six reports ninety litres more than yesterday. No intake recorded. No neighbouring tank shows a loss. I checked the sensor with a bucket and a marked stick, as instructed. The stick came back dry. The bucket came back full. Requesting a second bucket. Also requesting that whoever writes the instructions stop adding exclamation marks after the word simple. Update: the sample is salt water. We do not carry salt water. I have covered the inspection window because something on the other side is following the torch.", "starter_sentence": "The reading had changed overnight.", "word_count": 87, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "12e9f4e0-3181-5c98-820b-41291f00d814", "source_key": "sample-story-12e9f4e0-3181-5c98-820b-41291f00d814", "author_id": "3b608dd1-8159-5317-a916-27e58f6b5b9d"}, {"title": "Not her wedding", "content": "She said she wasn't coming which everyone took personally, but I thought she meant the photographer. She was pointing at his car. Or the car behind his car. Anyway by the time it reached our table it was the groom who wasn't coming and somebody had started putting the salads back in the fridge. I told them don't do that, you don't know anything yet. Neither did I but I was holding a plate so I looked involved. The bride came out in slippers and asked why her uncle was crying. He said happy tears. He'd been saying the marriage was a mistake thirty seconds before. Then the photographer arrived carrying a tyre and she said SEE. I still don't understand what that proved but we all went back for the salads.", "starter_sentence": "I only heard half the conversation.", "word_count": 132, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "4a6db8ef-c566-590d-9c29-219be4b91e1c", "source_key": "sample-story-4a6db8ef-c566-590d-9c29-219be4b91e1c", "author_id": "a5b516db-9000-59d2-b4e5-34ae6288fd48"}, {"title": "Below the ridge", "content": "My left sock had worked its way under my heel. I kept stopping to pull it up and my sister kept pretending to look at the view. When we reached the snow she went ahead. I watched her boots make two neat holes, two more. Mine slid sideways. Wind got under my coat and pushed it against my back. I wanted to say we should turn round but she had already sat down to untie her boots. She handed me one of her socks. Hers were much too big. We went another fifty metres before either of us spoke.", "starter_sentence": "We were nearly at the top.", "word_count": 99, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "4ac02c70-f34c-5ee9-a3a0-fe5eea638875", "source_key": "sample-story-4ac02c70-f34c-5ee9-a3a0-fe5eea638875", "author_id": "bce314a6-b6c0-517e-8519-b2b1289ea16e"}, {"title": "The passenger", "content": "I said forty kilometres. He said good. Put his sack in the back and got in. After ten minutes the sack crowed. I looked at him. He looked out the window. At the next village he paid for two passengers. I gave him change for one.", "starter_sentence": "He asked if I was going far.", "word_count": 46, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "421c3e6c-2642-5939-b117-5713eec9d2a3", "source_key": "sample-story-421c3e6c-2642-5939-b117-5713eec9d2a3", "author_id": "a4e73876-53a0-54d4-8be6-31ff102ddabe"}, {"title": "Spin cycle", "content": "the small grey cloud came out with the towels, i thought it was steam until it followed me to the balcony. shook the towel and it rained on my feet. well fine. put a bowl under it. it floated away from the bowl because apparently even weather can be difficult before breakfast. My neighbour leaned over and said hers had done that when she used too much powder. She had a whole thunderstorm in the spare room once. I asked how she got rid of it and she said she didnt, her son liked the noise for sleeping. The cloud settled over my basil. By evening the basil looked better than it had in months so I left the window open a crack, just enough for it to come in if it wanted", "starter_sentence": "There was something alive in the laundry.", "word_count": 133, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "834ba1a7-bbf8-5e89-ab41-583268f83300", "source_key": "sample-story-834ba1a7-bbf8-5e89-ab41-583268f83300", "author_id": "61179e3d-48ee-5367-9c5f-272ac8085853"}, {"title": "What came back", "content": "Returned: two mugs, one drill, the red blanket. Not returned: extension lead, three books, the lid for the big saucepan. In the drill case I found a photograph from the day we put the shelves up. Both of us covered in plaster dust. The shelves had fallen down before dinner because we'd used the wrong plugs and we'd eaten on the floor underneath the holes, laughing so much I thought the neighbour would knock. I added the photograph to the list. Crossed it out. Put the lidless saucepan on top of everything and carried it upstairs.", "starter_sentence": "We counted the boxes twice.", "word_count": 96, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "5622ce7d-4fea-5083-b98d-6f9da059bf57", "source_key": "sample-story-5622ce7d-4fea-5083-b98d-6f9da059bf57", "author_id": "c01828e7-2a62-56df-b08d-df4139dbce03"}, {"title": "The oranges", "content": "Take the oranges out of the plastic bag before you go in. The bag makes too much noise. Don't ask if she's tired. She'll say no and keep talking until she is. Pull the chair close enough that she doesn't have to raise her voice. Not that close, you're on the tube. When she asks about the garden tell her the truth about the roses and lie about the weeds. Peel an orange. She'll say she doesn't want it. Leave one piece on the napkin beside her hand. Talk about the bus, the rain, anything that happened outside. When she falls asleep stay until the piece of orange is gone or until", "starter_sentence": "They told me the visit had to be short.", "word_count": 112, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "532c513e-a1f6-55cc-8214-f54eabaf69bd", "source_key": "sample-story-532c513e-a1f6-55cc-8214-f54eabaf69bd", "author_id": "1c86406f-0ed6-51e0-a81e-08001b901bbb"}, {"title": "The spoon rule", "content": "I'm not against rules. I have rules. For example do not use my mug to grow an avocado. Apparently that was unreasonable because the avocado had roots already and moving it would cause stress. The avocado lives in my mug. I drink from a measuring jug. But now there's a rule about teaspoons, specifically that each person gets two, and I want to know who counted them because there were nine yesterday and there are four of us. Who has the ninth spoon. Is it communal. Is it for the avocado. Nobody will answer this directly. They say this is why we need a house meeting. I say a house meeting should require chairs and somebody has put all the chairs on the balcony to dry after washing them for reasons that were also not discussed", "starter_sentence": "There was a new note on the fridge.", "word_count": 136, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "7d056d4b-f699-5c60-8fd6-47400de9c2b0", "source_key": "sample-story-7d056d4b-f699-5c60-8fd6-47400de9c2b0", "author_id": "72801aaa-6c97-50f4-9640-48b16ec4b073"}, {"title": "Platform photograph", "content": "The boy's sleeve was caught under his mother's suitcase handle. He could have pulled it out. He stayed leaning sideways instead, one shoulder lower than the other. Behind them a man folded a newspaper into smaller and smaller squares without reading it. The train hadn't arrived. I lifted the camera. The boy looked straight at me and tucked his free hand into the trapped sleeve. In the photograph it looks as though his mother is holding him. Her own hands are both in her pockets.", "starter_sentence": "Only one person noticed the camera.", "word_count": 85, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "ea6b3334-245d-5bd4-805e-1da1cd1f4212", "source_key": "sample-story-ea6b3334-245d-5bd4-805e-1da1cd1f4212", "author_id": "fc425770-e917-5a6d-acc8-ca8daa11fc1b"}, {"title": "Number 46", "content": "Forty four. So I have time to work out what to say. Hello, I booked online. No obviously I booked online they have the booking. Just hello. Forty five goes in carrying a folder and I havent brought a folder. Was there a folder requirement. I look at the email again but the screen rotates and now it's huge and I can't find the bit with my name. A woman comes out and smiles at me in a way that might mean it's my turn or might just mean she is a person who smiles. I half stand. She walks past. Sit. The chair makes that noise. Everyone has heard the chair. Now I need to explain the chair before I can explain why I'm here. Forty six. I stand up properly and say sorry to the man who called my number. Haven't done anything yet. Already sorry.", "starter_sentence": "My number was almost next.", "word_count": 148, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "faa87a38-75da-516e-b01a-4a9a5f77e111", "source_key": "sample-story-faa87a38-75da-516e-b01a-4a9a5f77e111", "author_id": "eca9f8e7-f8b7-558f-8207-481485400330"}, {"title": "The wrong village", "content": "The important thing about that holiday was the cheese, although my wife says it was getting lost with no fuel, but we had some fuel, the light was only orange. We stopped in a village where a man was repairing a chair outside his shop and I asked him the way with the map upside down, which he politely turned round before telling me we were on the wrong side of the mountain. He gave us cheese while he explained. Very good cheese. I asked where to buy it and he said his brother made it and went inside to call him. My wife was in the car looking at the petrol light. The brother came on a motorbike with a whole wheel under his arm. We had to put it on her lap. She says this is the part of the story I should start with.", "starter_sentence": "We took the turning with the broken sign.", "word_count": 147, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "f3374cfe-c941-5c98-86b5-e22367a66c35", "source_key": "sample-story-f3374cfe-c941-5c98-86b5-e22367a66c35", "author_id": "5b0eeceb-76d5-583d-bed0-39afe01504fb"}, {"title": "The warm side", "content": "I turned the pillow over. The other side was warm too. I stood up. On the mattress, the hollow where I'd been lying began to deepen. Slowly, as though someone much heavier was settling into the space. I reached for the lamp and felt", "starter_sentence": "The room looked exactly as I had left it.", "word_count": 44, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "78e52dc9-e3ee-574c-885e-f5cfef1f1757", "source_key": "sample-story-78e52dc9-e3ee-574c-885e-f5cfef1f1757", "author_id": "69b1ca7b-7919-5593-9644-3ab1b8eb14e1"}, {"title": "Curtain rail", "content": "The first hole was fine. Second one hit something that made a noise I didn't recognise. Turned the drill off. Noise continued. Turned the radio off. Still going. It was my neighbour on the other side, drilling back. We met in the corridor holding identical drills like a very disappointing duel. He said he'd been putting up shelves. I said curtain rail. We compared the holes through his wall. Mine was higher. I felt pleased about that for no reason at all. Then his wife came out with the little bag of wall plugs we'd both forgotten to use.", "starter_sentence": "I said it would take ten minutes.", "word_count": 99, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "9d3523a2-e9c1-5de4-af22-c8c2886e259f", "source_key": "sample-story-9d3523a2-e9c1-5de4-af22-c8c2886e259f", "author_id": "2fee657f-01df-5589-9703-afda3541f074"}, {"title": "The end seat", "content": "She put her shopping on the end seat and kept looking at the door. The café filled. A man asked if the chair was taken and she said yes, quickly, then moved one bag to her lap as though that made it more convincing. I brought her another glass of water. She asked what time we closed. Four. Plenty of time, she said. At ten to four a woman in a cycling helmet came in and stood beside the chair. Neither smiled. The bags went on the floor. I was wiping the counter when I heard one of them say, I didn't know if you'd still be here. I left the cloth where it was and went to find something to do in the kitchen.", "starter_sentence": "She saved a place for someone who wasn't there.", "word_count": 125, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "e499097b-cd67-5140-a5c8-1068367e31bc", "source_key": "sample-story-e499097b-cd67-5140-a5c8-1068367e31bc", "author_id": "f353f630-d0c7-55ec-b980-d6a969560c1c"}, {"title": "One free minute", "content": "Buy one hour, get one minute free. I asked what kind of hour. Any kind, said the shopkeeper, except an hour you have already used. I bought an hour of sleep. He gave me an hour of waiting for sleep. I complained. You were in bed, he said. I asked for my free minute. He handed me a small paper bag. Inside was the minute before I had entered his shop. I used it to walk past. He came running after me asking for the bag back.", "starter_sentence": "The shopkeeper offered me a bargain.", "word_count": 87, "time_mode": 2, "mode": "custom", "is_hardcore": false, "id": "4bc23cd7-05be-5ff9-a591-8fa0cd313623", "source_key": "sample-story-4bc23cd7-05be-5ff9-a591-8fa0cd313623", "author_id": "d7117dcb-cf9f-5fc7-9a99-7f5ffc586ffb"}, {"title": "NOT our cat", "content": "found the cat!! carried him upstairs like a baby despite his opinions on this and rang mum to say stop looking. she said the cat is here. I said no he isnt he's in my ARMS. she said then who's eating tuna in my kitchen. looked down. this cat had a white foot. ours has no white feet. how many times have i looked at my own cat?? apparently not enough. tried taking him back down but he'd got comfortable and now i was the unreasonable one. downstairs there was a woman shaking a bag of treats and crying and i went over holding him out like an apology with legs. she hugged the cat then me then said he never lets strangers pick him up. great. exceptional talent discovered at last. accidental cat theft", "starter_sentence": "I was so relieved that I forgot to check.", "word_count": 135, "time_mode": 3, "mode": "custom", "is_hardcore": false, "id": "7cc36beb-809a-5641-b612-ba819eee47fe", "source_key": "sample-story-7cc36beb-809a-5641-b612-ba819eee47fe", "author_id": "72714dea-7aef-5a4a-8fd7-ad9f7a20e4aa"}, {"title": "Last carriage", "content": "A wet umbrella stood against the empty seat. At each station it leaned toward the open door, then straightened when the doors closed. I moved my bag so there would be room beside it.", "starter_sentence": "The rain stopped at the door.", "word_count": 34, "time_mode": 1, "mode": "custom", "is_hardcore": false, "id": "24cb4af3-4e23-5633-9a98-92205d216561", "source_key": "sample-story-24cb4af3-4e23-5633-9a98-92205d216561", "author_id": "757950cd-75de-5f59-ba49-d64a93bf4bcd"}]$initial$::jsonb)) ORDER BY author_username;
